"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ONBOARDING CHECKLIST: the first five things, ticked off
 *
 *   next       the first open task is open in place: what it is,
 *              why it matters and the one button that does it
 *   doing      its button spins while your action runs, then a
 *              check draws itself on the row, a strike draws
 *              through the label and the next task opens
 *   progress   a ring fills and "2 of 5" rolls with every tick
 *   pick       open any task by its row, done or not
 *   folded     the whole card folds to its header (ring and
 *              count) and opens again
 *   done       the list folds away, the ring fills and becomes a
 *              check with a small burst, and the title morphs to
 *              "You're all set"
 *
 * Drive it from your data (done per task) or let it keep its own.
 * ───────────────────────────────────────────────────────── */

export interface OnboardingTask {
  id: string;
  title: string;
  description?: string;
  /** The one button that does the task. Return a promise to show progress; it's ticked off when it resolves. */
  action?: {
    label: string;
    /** Shown while a promise runs, e.g. "Connecting". */ pendingLabel?: string;
    onClick?: () => void | Promise<unknown>;
    href?: string;
  };
  /** Controlled: whether it's done. Leave out to let the checklist track it. */
  done?: boolean;
}

export interface OnboardingChecklistProps extends React.HTMLAttributes<HTMLDivElement> {
  tasks: OnboardingTask[];
  title?: string;
  doneTitle?: string;
  doneDescription?: string;
  /** Called when a task is ticked off (its action resolved). */
  onTaskComplete?: (id: string) => void;
  /** Called with "Hide" once everything is done. */
  onDismiss?: () => void;
  defaultCollapsed?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
});

function Check({
  drawn,
  reduced,
  width = 2,
  delay = 80,
}: {
  drawn: boolean;
  reduced: boolean;
  width?: number;
  delay?: number;
}) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M4.2 8.4 6.8 11 11.8 5.4"
        stroke="currentColor"
        strokeWidth={width}
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${EASE} ${delay}ms`
              : "none",
        }}
      />
    </svg>
  );
}

/** The ring that fills with progress, and becomes a check with a small burst when it's full. */
function Ring({
  value,
  complete,
  reduced,
}: {
  value: number;
  complete: boolean;
  reduced: boolean;
}) {
  const c = 2 * Math.PI * 9;
  const burstRef = React.useRef<HTMLSpanElement>(null);
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (!complete || reduced) return;
    const dots = burstRef.current?.children;
    if (!dots) return;
    Array.from(dots).forEach((dot, i) => {
      const angle = (i / dots.length) * Math.PI * 2;
      const dist = 20 + (i % 2) * 6;
      (dot as HTMLElement).animate(
        [
          { transform: "translate(0,0) scale(1)", opacity: 0 },
          { opacity: 1, offset: 0.2 },
          {
            transform: `translate(${Math.cos(angle) * dist}px, ${Math.sin(angle) * dist}px) scale(0.4)`,
            opacity: 0,
          },
        ],
        { duration: 700, easing: EASE, delay: 260 },
      );
    });
  }, [complete, reduced]);
  return (
    <span
      aria-hidden="true"
      className="relative flex size-6 shrink-0 items-center justify-center"
    >
      <svg
        viewBox="0 0 24 24"
        className="absolute inset-0 size-full -rotate-90"
      >
        <circle
          cx="12"
          cy="12"
          r="9"
          fill="none"
          strokeWidth="2"
          className="stroke-border"
        />
        <circle
          cx="12"
          cy="12"
          r="9"
          fill="none"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={c}
          className="stroke-primary"
          style={{
            strokeDashoffset: c * (1 - value),
            transition: reduced ? "none" : `stroke-dashoffset 640ms ${EASE}`,
          }}
        />
      </svg>
      <span
        className="absolute inset-0 rounded-full bg-primary text-primary-foreground"
        style={{
          transform: complete ? "none" : "scale(0.4)",
          opacity: complete ? 1 : 0,
          transition: reduced
            ? "none"
            : `transform 460ms ${THROW} 180ms, opacity 260ms ${EASE} 180ms`,
        }}
      >
        <span className="absolute inset-[5px]">
          <Check drawn={complete} reduced={reduced} width={2.4} delay={360} />
        </span>
      </span>
      <span
        ref={burstRef}
        className="pointer-events-none absolute inset-0 flex items-center justify-center"
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span
            key={i}
            className="absolute size-1 rounded-full bg-primary opacity-0"
          />
        ))}
      </span>
    </span>
  );
}

export function OnboardingChecklist({
  tasks,
  title = "Get started",
  doneTitle = "You’re all set",
  doneDescription = "Everything’s in place. Here’s to the first busy Saturday.",
  onTaskComplete,
  onDismiss,
  defaultCollapsed = false,
  className = "",
  ...props
}: OnboardingChecklistProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState<Set<string>>(() => new Set());
  const [running, setRunning] = React.useState<string | null>(null);
  const [collapsed, setCollapsed] = React.useState(defaultCollapsed);
  const isDone = (t: OnboardingTask) => t.done ?? own.has(t.id);
  const firstOpen = tasks.find((t) => !isDone(t))?.id ?? null;
  const [picked, setPicked] = React.useState<string | null>(null);
  const openId = picked ?? firstOpen;
  const count = tasks.filter(isDone).length;
  const complete = count === tasks.length && tasks.length > 0;

  // When the open task gets done, the next open one takes over (unless someone picked a row since).
  const lastFirst = React.useRef(firstOpen);
  React.useEffect(() => {
    if (lastFirst.current !== firstOpen) {
      lastFirst.current = firstOpen;
      setPicked(null);
    }
  }, [firstOpen]);

  const run = async (task: OnboardingTask) => {
    if (!task.action || running) return;
    const result = task.action.onClick?.();
    if (task.action.href && !task.action.onClick) {
      window.location.assign(task.action.href);
      return;
    }
    if (result instanceof Promise) {
      setRunning(task.id);
      try {
        await result;
      } catch {
        setRunning(null);
        return;
      }
      setRunning(null);
    }
    if (task.done === undefined) setOwn((s) => new Set(s).add(task.id));
    onTaskComplete?.(task.id);
  };

  return (
    <section
      aria-labelledby={`${id}-title`}
      className={`w-full overflow-hidden rounded-[20px] border border-border bg-background ${className}`}
      {...props}
    >
      <div className="flex items-center gap-3 px-4 py-3.5">
        <Ring
          value={tasks.length ? count / tasks.length : 0}
          complete={complete}
          reduced={reduced}
        />
        <div className="min-w-0 flex-1">
          <h3
            id={`${id}-title`}
            className="text-[14px] font-medium leading-5 text-foreground"
          >
            <TextMorph>{complete ? doneTitle : title}</TextMorph>
          </h3>
          <p className="flex items-baseline gap-[0.3em] text-[12px] leading-4 text-muted-foreground tabular-nums">
            <NumberRoll value={count} duration={700} /> of {tasks.length} done
          </p>
        </div>
        <span role="status" className="sr-only">
          {complete ? doneTitle : `${count} of ${tasks.length} done`}
        </span>
        {complete && onDismiss ? (
          <button
            type="button"
            onClick={onDismiss}
            className={`cursor-pointer h-8 rounded-full px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent animate-[ui-fade-in_300ms_ease-out_400ms_both] motion-reduce:animate-none ${FOCUS}`}
          >
            Hide
          </button>
        ) : (
          <button
            type="button"
            aria-expanded={!collapsed}
            aria-controls={`${id}-list`}
            aria-label={collapsed ? "Show checklist" : "Fold checklist"}
            onClick={() => setCollapsed((c) => !c)}
            className={`cursor-pointer flex size-8 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <svg
              aria-hidden="true"
              viewBox="0 0 12 12"
              className="size-3 transition-transform duration-300 motion-reduce:transition-none"
              style={{
                transform: collapsed ? "none" : "rotate(180deg)",
                transitionTimingFunction: EASE,
              }}
            >
              <path
                d="m3 4.5 3 3 3-3"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}
      </div>

      {/* Done: the list folds away and a line says so. */}
      <div
        aria-hidden={!complete || undefined}
        className="grid"
        style={{
          gridTemplateRows: complete ? "1fr" : "0fr",
          opacity: complete ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${EASE} 200ms, opacity 360ms ${EASE} 320ms`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <p className="px-4 pb-4 text-[13px] leading-relaxed text-muted-foreground">
            {doneDescription}
          </p>
        </div>
      </div>

      <div
        id={`${id}-list`}
        inert={collapsed || complete}
        className="grid"
        style={{
          gridTemplateRows: collapsed || complete ? "0fr" : "1fr",
          opacity: collapsed || complete ? 0 : 1,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${EASE}, opacity ${collapsed || complete ? "180ms" : "360ms"} ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <ol className="border-t border-border p-1.5">
            {tasks.map((task, i) => {
              const done = isDone(task);
              const open = task.id === openId;
              const busy = running === task.id;
              return (
                <li
                  key={task.id}
                  className={`rounded-[14px] transition-colors duration-300 ${open ? "bg-accent/60" : ""}`}
                >
                  <button
                    type="button"
                    aria-expanded={open}
                    aria-controls={`${id}-t${i}`}
                    onClick={() =>
                      setPicked(
                        open
                          ? task.id === firstOpen
                            ? "__none__"
                            : null
                          : task.id,
                      )
                    }
                    className={`cursor-pointer flex w-full items-center gap-3 rounded-[14px] px-2.5 py-2.5 text-left ${FOCUS}`}
                  >
                    {/* An open ring that becomes a filled, drawn check. */}
                    <span
                      aria-hidden="true"
                      className="relative flex size-5 shrink-0 items-center justify-center"
                    >
                      <span
                        className="absolute inset-0 rounded-full shadow-[inset_0_0_0_1.5px_var(--border)]"
                        style={swap(!done, reduced)}
                      />
                      <span
                        className="absolute inset-0 rounded-full bg-foreground text-background"
                        style={swap(done, reduced)}
                      >
                        <Check drawn={done} reduced={reduced} />
                      </span>
                    </span>
                    <span className="min-w-0 flex-1 text-[13.5px]">
                      {/* The strike draws itself through the label once it's done. */}
                      <span
                        className={`bg-[linear-gradient(currentColor,currentColor)] bg-no-repeat [background-position:0_58%] transition-colors duration-300 ${done ? "text-muted-foreground" : "text-foreground"}`}
                        style={{
                          backgroundSize: done ? "100% 1px" : "0% 1px",
                          transition: reduced
                            ? "none"
                            : `background-size 480ms ${EASE} 120ms, color 300ms`,
                        }}
                      >
                        {task.title}
                      </span>
                      <span className="sr-only">{done ? ", done" : ""}</span>
                    </span>
                  </button>
                  <div
                    id={`${id}-t${i}`}
                    inert={!open}
                    className="grid"
                    style={{
                      gridTemplateRows: open ? "1fr" : "0fr",
                      opacity: open ? 1 : 0,
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 420ms ${EASE}, opacity ${open ? "320ms" : "140ms"} ${EASE}`,
                    }}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <div className="pb-3 pl-[42px] pr-3">
                        {task.description && (
                          <p className="text-[12.5px] leading-relaxed text-muted-foreground">
                            {task.description}
                          </p>
                        )}
                        {task.action && !done && (
                          <button
                            type="button"
                            onClick={() => run(task)}
                            aria-busy={busy || undefined}
                            className={`cursor-pointer mt-3 inline-flex h-8 items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-[background-color,transform] duration-200 hover:bg-primary/90 active:scale-[0.97] ${FOCUS}`}
                          >
                            <span
                              aria-hidden="true"
                              className="flex shrink-0 items-center justify-center overflow-hidden"
                              style={{
                                width: busy ? 18 : 0,
                                transition: reduced
                                  ? "none"
                                  : `width 320ms ${EASE}`,
                              }}
                            >
                              <span
                                className={`size-3 rounded-full border-[1.5px] border-primary-foreground/40 border-t-primary-foreground motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                              />
                            </span>
                            <TextMorph>
                              {busy
                                ? (task.action.pendingLabel ?? "Working on it")
                                : task.action.label}
                            </TextMorph>
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

